import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        Solver solver = new Solver();
        solver.solve(in, out);

        out.close();
    }

    static class Solver {
        void solve(InputReader in, PrintWriter out) {
            int a = in.nextInt();
            int b = in.nextInt();
            int l = in.nextInt();
            int r = in.nextInt();

            out.println(calc(a, b, l, r));
        }

        static int calc(int a, int b, int l, int r) {
            int period = a + b;

            if (r - l + 1 > 2 * period) {
                if (a <= b) return a + 1;
                return 2 * a - b;
            }

            int[] value = new int[3 * period + 1];
            int last = 0;

            for (int i = 1; i <= a; i++) {
                value[i] = i;
                last = i;
            }

            for (int i = a + 1; i <= period; i++) {
                value[i] = last;
            }

            for (int i = period + 1; i <= period + a; i++) {
                int candidate = 1;
                while (appears(value, candidate, b + 1, i - 1)) {
                    candidate++;
                }
                value[i] = candidate;
                last = candidate;
            }

            for (int i = period + a + 1; i <= 2 * period; i++) {
                value[i] = last;
            }

            for (int i = 2 * period + 1; i <= 3 * period; i++) {
                value[i] = value[i - period];
            }

            boolean[] hit = new boolean[25];
            int start = l % period;
            if (start == 0) start = period;
            int finish = r - l + start;
            if (finish < start) finish += period;

            for (int i = start; i <= finish; i++) {
                hit[value[i]] = true;
            }

            int answer = 0;
            for (int i = 1; i <= 24; i++) {
                if (hit[i]) answer++;
            }

            return answer;
        }

        static boolean appears(int[] arr, int v, int lo, int hi) {
            while (lo <= hi) {
                if (arr[lo++] == v) return true;
            }
            return false;
        }
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}
